\c postgres
drop database if exists assignment2 with (force);
create database assignment2;
\c assignment2

-- Now connected to an empty A2 DB and ready to begin. 
\set ECHO none
\set QUIET on
\timing off

\echo 'Creating tables and inserting data...'

BEGIN TRANSACTION;

CREATE TABLE actor (
  actor_id INTEGER PRIMARY KEY,
  first_name VARCHAR(45) NOT NULL,
  last_name VARCHAR(45) NOT NULL
);

CREATE TABLE category (
  category_id INTEGER PRIMARY KEY,
  name VARCHAR(25) NOT NULL
);

CREATE TABLE language (
  language_id INTEGER PRIMARY KEY,
  name VARCHAR(20) NOT NULL
);

CREATE TABLE film (
  film_id INTEGER CONSTRAINT PK_FILMID PRIMARY KEY,
  title VARCHAR(255) NOT NULL,
  description VARCHAR(255) NOT NULL,
  release_year INTEGER DEFAULT NULL,
  language_id INTEGER DEFAULT NULL,
  original_language_id INTEGER DEFAULT NULL,
  rental_duration INTEGER DEFAULT 3 NOT NULL,
  rental_rate NUMERIC(4,2) DEFAULT '4.99' NOT NULL,
  length INTEGER DEFAULT NULL,
  replacement_cost NUMERIC(5,2) DEFAULT '19.99' NOT NULL,
  rating VARCHAR(8) DEFAULT 'G' NOT NULL,
  special_features VARCHAR(255) DEFAULT NULL,
  FOREIGN KEY (language_id) REFERENCES language,
  FOREIGN KEY (original_language_id) REFERENCES language
);

CREATE TABLE film_actor (
  actor_id INTEGER NOT NULL,
  film_id INTEGER NOT NULL,
  FOREIGN KEY (actor_id) REFERENCES actor,
  FOREIGN KEY (film_id) REFERENCES film
);

CREATE TABLE film_category (
  film_id INTEGER NOT NULL,
  category_id INTEGER NOT NULL,
  FOREIGN KEY (film_id) REFERENCES film,
  FOREIGN KEY (category_id) REFERENCES category
);

-- 
































































































COMMIT;

ANALYZE ACTOR, CATEGORY, FILM, FILM_ACTOR, FILM_CATEGORY, LANGUAGE;

\echo 'DONE! All data has been inserted.'

\set QUIET off
\set ECHO all


